import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException, forwardRef } from '@nestjs/common';
import { InfluxModule } from '../influx/influx.module';
import { CustomerService } from './customer.service';
import { SchedulerModule } from '../scheduler/scheduler.module';
import { SchedulerService } from '../scheduler/scheduler.service';
import { PrivateAPIServicesModule } from '../services/services.module';
import { PrivateAPIOfferingModule } from '../offering/offering.module';
import { UsageModule } from '../usage/usage.module';
import { InfluxService } from '../influx/influx.service';
import { schedulerType, SchedulerStatus, SupportedMeasurementFrequencies } from '../scheduler/dto/scheduler.dto';
import { paymentChannel } from './dto/create-customer.dto';
import { BillingService } from '../billing/billing.service';
import { BillingModule } from '../billing/billing.module';
import { AuditService } from '../audit/audit.service';
import { UsageService } from '../usage/usage.service';

describe('tmp migration checks', () => {
    let service: CustomerService;
    let scheduler: SchedulerService;
    let influx: InfluxService;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [CustomerService],
            imports: [
                InfluxModule,
                forwardRef(() => SchedulerModule),
                forwardRef(() => PrivateAPIServicesModule),
                forwardRef(() => PrivateAPIOfferingModule),
                forwardRef(() => UsageModule),
            ],
        }).compile();

        service = module.get<CustomerService>(CustomerService);
        scheduler = module.get<SchedulerService>(SchedulerService);
        influx = module.get<InfluxService>(InfluxService);
        influx.loadPoints = jest.fn().mockResolvedValue(undefined);
        jest.spyOn(scheduler, 'create').mockResolvedValue({ message: 'ok', data: [] });
        jest.spyOn(scheduler, 'remove').mockResolvedValue({ message: 'ok', data: [] });
    });

    it('does not create a schedule without an offering', async () => {
        await service.create({ customerName: 'a', businessID: 'biz', email: '', paymentChannel: null }, 'sub-1');
        expect(scheduler.create).not.toHaveBeenCalled();
    });

    it('creates a monthly billing schedule when an offering exists', async () => {
        const res = await service.create(
            { customerName: 'a', businessID: 'biz', email: '', paymentChannel: null, offeringId: 'off-1' },
            'sub-1'
        );
        expect(scheduler.create).toHaveBeenCalledWith({
            schedulerID: res.customerId,
            schedulerType: schedulerType.billing,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: { customerId: res.customerId, businessID: 'biz' },
            rate: SupportedMeasurementFrequencies.monthly,
            subject: 'sub-1',
            businessID: 'biz',
        });
    });

    it('replaces the schedule when the offeringId changes and tolerates missing schedules', async () => {
        jest.spyOn(service, 'findOne').mockResolvedValue({
            message: 'Found Customer',
            data: [
                {
                    customerId: 'cust-1',
                    customerName: 'a',
                    paymentChannel: paymentChannel.Stripe,
                    offeringId: 'old-offering',
                } as never,
            ],
        });
        (scheduler.remove as jest.Mock).mockRejectedValueOnce(new NotFoundException('nope'));
        await service.update({ customerId: 'cust-1', businessID: 'biz', offeringId: 'new-offering' }, 'sub-2');
        expect(scheduler.remove).toHaveBeenCalledWith({
            schedulerID: 'cust-1',
            businessID: 'biz',
            isBillingQueue: true,
        });
        expect(scheduler.create).toHaveBeenCalledWith(
            expect.objectContaining({
                schedulerID: 'cust-1',
                businessID: 'biz',
                subject: 'sub-2',
                schedulerType: schedulerType.billing,
                rate: SupportedMeasurementFrequencies.monthly,
                scheduleParameters: { customerId: 'cust-1', businessID: 'biz' },
            })
        );
    });

    it('does not touch the schedule when the offeringId is unchanged', async () => {
        jest.spyOn(service, 'findOne').mockResolvedValue({
            message: 'Found Customer',
            data: [{ customerId: 'cust-1', customerName: 'a', offeringId: 'same' } as never],
        });
        await service.update({ customerId: 'cust-1', businessID: 'biz', offeringId: 'same' });
        expect(scheduler.remove).not.toHaveBeenCalled();
        expect(scheduler.create).not.toHaveBeenCalled();
    });

    it('emits billing jobs on the billing queue', async () => {
        // eslint-disable-next-line @typescript-eslint/dot-notation
        const billingQueue = scheduler['billingQueue'];
        // eslint-disable-next-line @typescript-eslint/dot-notation
        const normalQueue = scheduler['queue'];
        billingQueue.add = jest.fn();
        normalQueue.add = jest.fn();
        await scheduler.emitOne({
            schedulerId: 'sched-1',
            payload: {
                schedulerType: schedulerType.billing,
                businessID: 'biz',
                scheduleParameters: { customerId: 'cust-1' },
            },
        });
        expect(billingQueue.add).toHaveBeenCalledWith(
            'billingReport',
            expect.objectContaining({ schedulerID: 'sched-1', businessID: 'biz' })
        );
        expect(normalQueue.add).not.toHaveBeenCalled();

        await scheduler.emitOne({
            schedulerId: 'sched-2',
            payload: {
                schedulerType: schedulerType.dimensionDataGathering,
                dimensionType: 'ebsVolume',
                businessID: 'biz',
                scheduleParameters: {},
            },
        });
        expect(normalQueue.add).toHaveBeenCalledWith('ebsVolume', expect.objectContaining({ schedulerID: 'sched-2' }));
    });
});

