            message: 'Found Customer',
            data: [{ customerId: 'cust-1', offering: { billingCycle: 'monthly' } } as never],
        });
        jest.spyOn(billing.invoicesService, 'generateInvoiceForUsageTotal').mockRejectedValue(new Error('boom'));
        const auditSpy = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
        await expect(
            billing.create({
                data: { businessID: 'biz', scheduleParameters: { customerId: 'cust-1', businessID: undefined } },
            } as never)
        ).resolves.toBeUndefined();
        expect(auditSpy).toHaveBeenCalled();
        expect(influx.loadPoints).not.toHaveBeenCalled();
    });

    it('returns empty usage for a customer without an offering', async () => {
        const usageService = module.get<UsageService>(UsageService);
        jest.spyOn(usageService.customerService, 'findOne').mockResolvedValue({
            message: 'Found Customer',
            data: [{ customerId: 'cust-1' } as never],
        });
        await expect(usageService.findUsageForCustomer({ customerId: 'cust-1', businessID: 'biz' }, {})).resolves.toEqual(
            []
        );
    });
});

