import { Inject, Injectable, Logger, Optional, forwardRef } from '@nestjs/common';
import { ServicesService } from '../services/services.service';
import { InfluxService } from '../influx/influx.service';
import { InvoicesService } from '../invoice/invoices.service';
import { Billing, billingScheduleConsumers } from './entities/billing.entity';
import { randomUUID } from 'crypto';
import { Process, Processor } from '@nestjs/bull';
import { CreateBillingReportDto } from './dto/createBillingReport.dto';
import { Job } from 'bull';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity';
import { CustomerService } from '../customer/customer.service';
import { OfferingService } from '../offering/offering.service';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';
import { ReadOfferingResponseData } from '../offering/dto/readOffering.dto';

@Processor('scheduler_billing_queue')
export class BillingService {
    private static readonly logger = new Logger(BillingService.name);
    constructor(
        readonly InfluxService: InfluxService,
        @Optional() @Inject(forwardRef(() => ServicesService)) readonly servicesService?: ServicesService,
        @Optional() @Inject(forwardRef(() => InvoicesService)) readonly invoicesService?: InvoicesService,
        @Optional() @Inject(forwardRef(() => CustomerService)) readonly customerService?: CustomerService,
        @Optional() @Inject(forwardRef(() => OfferingService)) readonly offeringService?: OfferingService
    ) {}

    /**
     * Billing is scheduled per customer, the scheduler record carries the businessID while the
     * customerId is passed along inside of the schedule parameters.
     */
    @Process({ name: billingScheduleConsumers.billingReport })
    async create({ data: { scheduleParameters, businessID } }: Job<SchedulerEntity>) {
        const { customerId } = (scheduleParameters ?? {}) as CreateBillingReportDto;
        try {
            // 1. Resolve the customer and the offering it is subscribed to
            const offering = await this.findOfferingForCustomer({ customerId, businessID });
            if (!offering) {
                BillingService.logger.log(
                    `No offering found for customer: ${customerId} in business: ${businessID}, nothing to bill`
                );
                return;
            }
            // 2. The billing cycle of the offering determines the time range that gets billed
            const { startTime, endTime } = Billing.billingCycleToTimeRange(offering.billingCycle);
            BillingService.logger.log(
                `Generating an invoice for customer: ${customerId} between ${startTime} and ${endTime}`
            );
            // 3. Build the invoice out of the usage totals of the customer for that time range
            const { invoiceId } = await this.invoicesService.generateInvoiceForUsageTotal({
                businessID,
                customerId,
                start: startTime,
                end: endTime,
            });
            const entity = new Billing({
                invoiceId,
                businessID,
                customerId,
                startTime,
                endTime,
                billingId: randomUUID(),
            });
            // 4. Save the billing information to the ledger
            const point = Billing.transformer(entity, this.InfluxService);
            await this.InfluxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, 'paigo', [point]);
        } catch (error) {
            // A failed run must not leave a partially stored billing record behind, report it instead
            AuditService.publishEvent({
                message: `Error occurred while generating the billing report for customer: ${customerId} in business: ${businessID}`,
                data: [error],
                topic: AuditScope.ERROR,
            });
        }
    }

    private async findOfferingForCustomer({
        customerId,
        businessID,
    }: {
        customerId: string;
        businessID: string;
    }): Promise<ReadOfferingResponseData> {
        const {
            data: [customer],
        } = await this.getCustomerService().findOne({ customerId, businessID });
        if (customer?.offering) {
            return customer.offering;
        }
        if (customer?.offeringId && this.offeringService) {
            const {
                data: [offering],
            } = await this.offeringService.findOne({ businessID, offeringId: customer.offeringId });
            return offering;
        }
        return undefined;
    }

    private getCustomerService(): CustomerService {
        // The customer service is also reachable through the invoice and service modules, which keeps
        // the processor working when it gets instantiated without the customer module directly attached
        return this.customerService ?? this.invoicesService?.customerService ?? this.servicesService?.customerService;
    }
}

