async emitOne({ schedulerId, payload }) {
    const { dimensionType, ...rest } = payload;
    const schedulerEntity = new SchedulerEntity({ schedulerID: schedulerId, ...rest });
    const isBillingJob =
        schedulerEntity.schedulerType === schedulerType.billing ||
        dimensionType === schedulerType.billing ||
        dimensionType === billingScheduleConsumers.billingReport;
    if (isBillingJob) {
        SchedulerService.logger.log('Emitting a billing job onto the billing queue');
        await this.billingQueue.add(billingScheduleConsumers.billingReport, { ...schedulerEntity });
    } else {
        await this.queue.add(dimensionType, schedulerEntity);
    }
    return { message: 'completed' };
}

